package top.dcpstudios.calendarwidget;

import android.app.*;import android.graphics.Typeface;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

final class DirectoryScreen {
 final MainActivity a;final String kind;String query="";JSONObject data;LinearLayout list;ScrollView scroll;int position;
 DirectoryScreen(MainActivity a,String kind){this.a=a;this.kind=kind;}
 void show(){a.base("directory");a.root.addView(a.button("‹ 设置",a::settings));LinearLayout header=new LinearLayout(a);header.setGravity(Gravity.CENTER_VERTICAL);TextView title=a.text(kind.equals("group")?"群聊":"联系人",26,a.ink);title.setTypeface(null,Typeface.BOLD);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));header.addView(a.button("分类管理",()->{if(data!=null)AttentionSettings.categories(a,kind,data.optJSONObject("settings"));}),new LinearLayout.LayoutParams(a.d(88),a.d(40)));a.root.addView(header);
  EditText search=new EditText(a);search.setSingleLine();search.setTextSize(13);search.setTextColor(a.ink);search.setHintTextColor(a.muted);search.setHint("搜索备注、昵称、分类");search.setPadding(a.d(12),0,a.d(12),0);search.setBackground(a.bg(a.surface,8));a.root.addView(search,new LinearLayout.LayoutParams(-1,a.d(40)));a.space(a.root,8);scroll=new ScrollView(a);list=a.column();scroll.addView(list);a.root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString();position=0;render();}public void afterTextChanged(Editable e){}});reload();
 }
 void reload(){TerminalSettings.run(a,()->{NetDiskSession.Reply result=TerminalClient.requestBound(a,"/directory",null,null);NetDiskSession.ui(a,result.account,()->{data=result.data;if("directory".equals(a.page)){render();scroll.post(()->scroll.scrollTo(0,position));}});return null;});}
 static String remark(JSONObject r){String v=r.optString("note").trim();return v.isEmpty()?r.optString("wx_remark").trim():v;}
 static String display(JSONObject r){String note=remark(r),name=r.optString("name");return note.isEmpty()||note.equals(name)?name:note+"（"+name+"）";}
 static JSONArray tags(JSONObject r){JSONArray tags=r.optJSONArray("categories");return tags==null?new JSONArray().put(r.optString("category","其它")):tags;}
 void render(){if(data==null||list==null)return;list.removeAllViews();ArrayList<JSONObject> rows=new ArrayList<>();JSONArray items=data.optJSONArray("items");for(int i=0;i<items.length();i++){JSONObject r=items.optJSONObject(i);String match=display(r)+tags(r)+r.optString("username");if(kind.equals(r.optString("kind"))&&match.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))rows.add(r);}
  java.text.Collator collator=java.text.Collator.getInstance(Locale.CHINA);Collections.sort(rows,(x,y)->collator.compare(remark(x).isEmpty()?x.optString("name"):remark(x),remark(y).isEmpty()?y.optString("name"):remark(y)));
  String last="";for(JSONObject r:rows){String name=display(r);String initial=name.isEmpty()?"#":name.substring(0,1);if(!initial.equals(last)){TextView section=a.text(initial,11,a.muted);section.setPadding(a.d(8),a.d(8),0,a.d(4));list.addView(section);last=initial;}
   LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(a.d(8),a.d(10),a.d(8),a.d(10));a.touch(row,a.surface);TextView avatar=a.text(initial,18,0xFFFFFFFF);avatar.setGravity(Gravity.CENTER);avatar.setBackground(a.bg(kind.equals("group")?0xFF3F8C7D:0xFF5485A7,8));row.addView(avatar,new LinearLayout.LayoutParams(a.d(40),a.d(40)));LinearLayout info=a.column();info.setPadding(a.d(12),0,a.d(8),0);TextView n=a.text(name,14,a.ink);n.setTypeface(null,Typeface.BOLD);info.addView(n);JSONArray tags=tags(r);ArrayList<String> names=new ArrayList<>();for(int i=0;i<tags.length();i++)names.add(tags.optString(i));TextView sub=a.text((names.isEmpty()?"未分类":TextUtils.join(" · ",names))+(kind.equals("group")?(r.isNull("muted")?" · 免打扰未知":r.optInt("muted")==1?" · 已免打扰":" · 可提醒"):""),11,a.muted);info.addView(sub);row.addView(info,new LinearLayout.LayoutParams(0,-2,1));row.addView(a.text("›",18,a.muted));row.setOnClickListener(v->{position=scroll.getScrollY();edit(r);});Ui.press(row);list.addView(row);View line=new View(a);line.setBackgroundColor(a.line);list.addView(line,new LinearLayout.LayoutParams(-1,a.d(1)));}
  if(rows.isEmpty())list.addView(a.text("没有匹配的联系人或群聊",13,a.muted));
 }
 void edit(JSONObject row){try{LinearLayout form=a.column();form.setPadding(a.d(16),a.d(8),a.d(16),a.d(8));EditText note=TerminalSettings.input(a,form,"我的备注",row.optString("note"),false);Ui.label(a,form,"分类");LinkedHashSet<String> selected=new LinkedHashSet<>();JSONArray old=tags(row);for(int i=0;i<old.length();i++)selected.add(old.getString(i));LinkedHashSet<String> all=new LinkedHashSet<>(Arrays.asList(AttentionSettings.strings(data.getJSONObject("settings").getJSONObject("categories").getJSONArray(kind))));all.addAll(selected);LinearLayout tagRow=null;int i=0;for(String cat:all){if(i++%2==0){tagRow=new LinearLayout(a);form.addView(tagRow);}CheckBox check=new CheckBox(a);check.setText(cat);check.setTextSize(13);check.setTextColor(a.ink);check.setChecked(selected.contains(cat));check.setOnCheckedChangeListener((v,on)->{if(on)selected.add(cat);else selected.remove(cat);});tagRow.addView(check,new LinearLayout.LayoutParams(0,a.d(40),1));}
  Ui.divider(a,form);Ui.Choice action=AttentionSettings.choice(a,form,"消息处理",new String[]{"跟随","提醒","静默","忽略"},AttentionSettings.index(AttentionSettings.ACTIONS,row.optString("action")));String[] kinds=new String[AttentionSettings.KINDS.length+1];kinds[0]="按分类推断";System.arraycopy(AttentionSettings.KINDS,0,kinds,1,AttentionSettings.KINDS.length);Ui.Choice messageKind=AttentionSettings.choice(a,form,"消息类型",kinds,AttentionSettings.index(AttentionSettings.KINDS,row.optString("message_kind"))+1);if(kind.equals("group"))form.addView(a.text("微信免打扰（只读）："+(row.isNull("muted")?"未知":row.optInt("muted")==1?"已开启":"未开启"),11,a.muted));
  ScrollView box=new ScrollView(a);box.addView(form);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(row.optString("name")).setView(box).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{JSONObject patch=new JSONObject().put("categories",new JSONArray(selected)).put("note",note.getText().toString()).put("action",AttentionSettings.ACTIONS[action.getSelectedItemPosition()]).put("message_kind",messageKind.getSelectedItemPosition()==0?"":AttentionSettings.KINDS[messageKind.getSelectedItemPosition()-1]);TerminalSettings.run(a,()->{TerminalClient.request(a,"/directory/"+android.net.Uri.encode(row.getString("username")),patch);a.runOnUiThread(()->{dialog.dismiss();reload();});return "已保存";});}catch(Exception e){a.error(e);}}));dialog.show();
 }catch(Exception e){a.error(e);}}
}
